/* ============================================================
   Stock Dashboard – style.css
   ============================================================ */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Segoe UI', Arial, sans-serif;
  background: #0f1117;
  color: #e2e8f0;
  min-height: 100vh;
  overflow-x: hidden;
}

/* ── Header ── */
#header {
  padding: 18px 32px 14px;
  background: #161b27;
  border-bottom: 1px solid #2d3748;
}

#header h1 {
  font-size: 1.45rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #f0f4ff;
}

#header p {
  font-size: 0.82rem;
  color: #8896a8;
  margin-top: 3px;
}

/* ── Main layout ── */
#main {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 24px;
  padding: 24px 28px;
  width: 100%;
}

/* ── Bubble chart panel ── */
#chart-panel {
  flex: 0 0 auto;
  background: #161b27;
  border: 1px solid #2d3748;
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

#chart-panel h2 {
  font-size: 0.92rem;
  font-weight: 600;
  color: #a0aec0;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 12px;
  align-self: flex-start;
}

#bubble-chart {
  display: block;
}

/* bubbles */
.bubble {
  cursor: pointer;
  stroke-width: 1.5;
}

.bubble:hover {
  stroke-width: 2.5;
  filter: brightness(1.25);
}

.bubble.selected {
  stroke: #fff;
  stroke-width: 3;
  filter: brightness(1.35);
}

.bubble-label {
  pointer-events: none;
  fill: #fff;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
  text-shadow: 0 1px 3px rgba(0,0,0,0.8);
}

/* ── Legend ── */
#legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin-top: 14px;
  padding: 0 4px;
  width: 100%;
  justify-content: center;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  color: #c4cede;
  cursor: pointer;
  user-select: none;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ── Table panel ── */
#table-panel {
  flex: 1 1 0;
  background: #161b27;
  border: 1px solid #2d3748;
  border-radius: 10px;
  padding: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

#table-panel h2 {
  font-size: 0.92rem;
  font-weight: 600;
  color: #a0aec0;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 12px;
}

#table-wrap {
  overflow-y: auto;
  max-height: 640px;
  border: 1px solid #2d3748;
  border-radius: 6px;
}

#table-wrap::-webkit-scrollbar {
  width: 6px;
}
#table-wrap::-webkit-scrollbar-track {
  background: #1a2035;
}
#table-wrap::-webkit-scrollbar-thumb {
  background: #3a4a6b;
  border-radius: 3px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.83rem;
}

thead {
  position: sticky;
  top: 0;
  z-index: 2;
}

thead th {
  background: #1e2738;
  color: #94a3b8;
  font-weight: 600;
  text-align: left;
  padding: 10px 14px;
  border-bottom: 1px solid #2d3748;
  white-space: nowrap;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 0.75rem;
}

tbody tr {
  border-bottom: 1px solid #1e2738;
  cursor: pointer;
  transition: background 0.12s;
}

tbody tr:last-child {
  border-bottom: none;
}

tbody tr:hover {
  background: #1e293b;
}

tbody tr.selected {
  background: #1e3a5f;
  outline: 1px solid #3b82f6;
  outline-offset: -1px;
}

tbody td {
  padding: 9px 14px;
  color: #d1d9e6;
  vertical-align: middle;
}

td.ticker-cell {
  font-weight: 700;
  font-family: 'Courier New', monospace;
  font-size: 0.88rem;
  color: #f0f4ff;
}

td.sector-cell {
  font-size: 0.78rem;
}

td.cap-cell {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: #7dd3b0;
}

/* sector badge */
.sector-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

/* ── Tooltip ── */
#tooltip {
  position: fixed;
  padding: 10px 14px;
  background: rgba(10, 15, 30, 0.93);
  border: 1px solid #3b4a6b;
  color: #e2e8f0;
  border-radius: 7px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s;
  z-index: 1000;
  font-size: 0.83rem;
  max-width: 240px;
  line-height: 1.55;
  box-shadow: 0 4px 20px rgba(0,0,0,0.55);
}

#tooltip.visible {
  opacity: 1;
}

#tooltip .tt-ticker {
  font-size: 1rem;
  font-weight: 700;
  color: #f0f4ff;
  margin-bottom: 3px;
}

#tooltip .tt-name {
  color: #94a3b8;
  font-size: 0.78rem;
  margin-bottom: 5px;
}

#tooltip .tt-row {
  display: flex;
  gap: 6px;
}

#tooltip .tt-label {
  color: #64748b;
  min-width: 55px;
}

#tooltip .tt-val {
  color: #cbd5e1;
}

/* ============================================================
   visualization.js – Stock Bubble Chart + Data Table
   D3.js v6  |  Deterministic force simulation
   ============================================================
   Defaults used where not specified:
     - Chart width: 680px, height: 660px
     - Bubble radius range: 14–52px
     - ETF bubble radius: 18px (uniform, no market-cap data)
     - Force simulation: 300 fixed ticks, no animation
     - Sector cluster centres evenly spaced on a 3×2 grid
   ============================================================ */

(function () {
  "use strict";

  /* ── Constants ── */
  const CHART_W = 700;
  const CHART_H = 660;
  const R_MIN = 14;
  const R_MAX = 52;
  const R_ETF = 18;
  const SIM_TICKS = 400;

  /* Sector colour palette – deterministic assignment */
  const SECTOR_ORDER = [
    "Information Technology",
    "Financial",
    "Energy",
    "Industry",
    "ETF",
  ];

  const SECTOR_COLORS = {
    "Information Technology": "#4f8ef7",
    "Financial":              "#f7a84f",
    "Energy":                 "#4fc97a",
    "Industry":               "#e05c8a",
    "ETF":                    "#a78bfa",
  };

  /* Sector cluster centres – laid out on a grid inside the SVG */
  const SECTOR_CENTERS = {
    "Information Technology": { x: CHART_W * 0.26, y: CHART_H * 0.30 },
    "Financial":              { x: CHART_W * 0.74, y: CHART_H * 0.30 },
    "Energy":                 { x: CHART_W * 0.26, y: CHART_H * 0.72 },
    "Industry":               { x: CHART_W * 0.74, y: CHART_H * 0.72 },
    "ETF":                    { x: CHART_W * 0.50, y: CHART_H * 0.50 },
  };

  /* ── State ── */
  let selectedTicker = null;

  /* ── Helpers ── */
  function formatMarketCap(val) {
    if (val == null || isNaN(val)) return "—";
    if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
    if (val >= 1e9)  return (val / 1e9).toFixed(2)  + "B";
    if (val >= 1e6)  return (val / 1e6).toFixed(2)  + "M";
    return val.toFixed(0);
  }

  function isEtf(d) {
    return d.sector === "ETF";
  }

  /* ── Load & parse CSV ── */
  d3.csv("data/stock-descriptions.csv").then(function (raw) {

    /* Parse and sort deterministically by ticker */
    const data = raw
      .map(function (d) {
        return {
          ticker:     d.ticker ? d.ticker.trim() : "",
          sector:     d.sector ? d.sector.trim() : "ETF",
          name:       d["full name"] ? d["full name"].trim() : "",
          marketCap:  d.marketCap && d.marketCap !== "" ? +d.marketCap : null,
          country:    d.country ? d.country.trim() : null,
          website:    d.website ? d.website.trim() : null,
        };
      })
      .filter(function (d) { return d.ticker !== ""; })
      .sort(function (a, b) { return d3.ascending(a.ticker, b.ticker); });

    /* Radius scale (only for non-ETF) */
    const capExtent = d3.extent(
      data.filter(function (d) { return !isEtf(d) && d.marketCap != null; }),
      function (d) { return d.marketCap; }
    );
    const rScale = d3.scaleSqrt()
      .domain(capExtent)
      .range([R_MIN, R_MAX]);

    function radius(d) {
      if (isEtf(d) || d.marketCap == null) return R_ETF;
      return rScale(d.marketCap);
    }

    /* Assign deterministic initial positions based on sector cluster */
    data.forEach(function (d) {
      const centre = SECTOR_CENTERS[d.sector] || { x: CHART_W / 2, y: CHART_H / 2 };
      d.x = centre.x + (Math.sin(d.ticker.charCodeAt(0) * 7) * 40);
      d.y = centre.y + (Math.cos(d.ticker.charCodeAt(0) * 11) * 40);
      d.r = radius(d);
    });

    /* ── Force simulation (fixed tick count, no animation) ── */
    const sim = d3.forceSimulation(data)
      .force("x", d3.forceX(function (d) {
        return (SECTOR_CENTERS[d.sector] || { x: CHART_W / 2 }).x;
      }).strength(0.12))
      .force("y", d3.forceY(function (d) {
        return (SECTOR_CENTERS[d.sector] || { y: CHART_H / 2 }).y;
      }).strength(0.12))
      .force("collide", d3.forceCollide(function (d) {
        return d.r + 2.5;
      }).strength(1).iterations(4))
      .stop();

    for (let i = 0; i < SIM_TICKS; i++) sim.tick();

    /* Clamp positions so bubbles stay inside SVG */
    data.forEach(function (d) {
      d.x = Math.max(d.r + 2, Math.min(CHART_W - d.r - 2, d.x));
      d.y = Math.max(d.r + 2, Math.min(CHART_H - d.r - 2, d.y));
    });

    /* ── Build SVG ── */
    buildBubbleChart(data);
    buildTable(data);

  }).catch(function (err) {
    console.error("Failed to load stock data:", err);
  });

  /* ── Bubble Chart ── */
  function buildBubbleChart(data) {
    const svg = d3.select("#bubble-chart")
      .attr("width",  CHART_W)
      .attr("height", CHART_H)
      .attr("viewBox", "0 0 " + CHART_W + " " + CHART_H);

    /* Sector cluster label backgrounds (subtle) */
    const sectorGroups = d3.group(data, function (d) { return d.sector; });

    /* Draw bubbles */
    const node = svg.selectAll("g.node")
      .data(data, function (d) { return d.ticker; })
      .join("g")
      .attr("class", "node")
      .attr("transform", function (d) {
        return "translate(" + d.x + "," + d.y + ")";
      });

    node.append("circle")
      .attr("class", "bubble")
      .attr("r", function (d) { return d.r; })
      .attr("fill", function (d) {
        return SECTOR_COLORS[d.sector] || "#888";
      })
      .attr("stroke", function (d) {
        return d3.color(SECTOR_COLORS[d.sector] || "#888").darker(0.8);
      })
      .attr("stroke-width", 1.5)
      .attr("fill-opacity", 0.88);

    /* Ticker label – only show if bubble is large enough */
    node.append("text")
      .attr("class", "bubble-label")
      .attr("dy", "0.35em")
      .style("font-size", function (d) {
        const fs = Math.min(d.r * 0.52, 13);
        return fs + "px";
      })
      .text(function (d) {
        /* truncate if tiny bubble */
        if (d.r < 16) return d.ticker.length <= 3 ? d.ticker : d.ticker.slice(0, 2);
        return d.ticker;
      });

    /* ── Interactions ── */
    const tooltip = d3.select("#tooltip");

    node.on("mouseover", function (event, d) {
        if (isEtf(d)) return;
        tooltip
          .classed("visible", true)
          .html(
            '<div class="tt-ticker">' + d.ticker + '</div>' +
            '<div class="tt-name">'   + d.name   + '</div>' +
            '<div class="tt-row"><span class="tt-label">Sector</span><span class="tt-val">' + d.sector + '</span></div>' +
            (d.marketCap != null
              ? '<div class="tt-row"><span class="tt-label">Mkt Cap</span><span class="tt-val">' + formatMarketCap(d.marketCap) + '</span></div>'
              : '')
          )
          .style("left", (event.clientX + 14) + "px")
          .style("top",  (event.clientY - 14) + "px");
      })
      .on("mousemove", function (event, d) {
        if (isEtf(d)) return;
        tooltip
          .style("left", (event.clientX + 14) + "px")
          .style("top",  (event.clientY - 14) + "px");
      })
      .on("mouseout", function () {
        tooltip.classed("visible", false);
      })
      .on("click", function (event, d) {
        event.stopPropagation();
        if (selectedTicker === d.ticker) {
          clearSelection();
        } else {
          selectTicker(d.ticker);
        }
      });

    /* Click on SVG background → deselect */
    svg.on("click", function () { clearSelection(); });

    /* Store reference for selection updates */
    window._bubbleNodes = node;

    /* ── Legend ── */
    const legend = d3.select("#legend");
    SECTOR_ORDER.forEach(function (sector) {
      if (!sectorGroups.has(sector)) return;
      const item = legend.append("div").attr("class", "legend-item");
      item.append("div")
        .attr("class", "legend-swatch")
        .style("background", SECTOR_COLORS[sector] || "#888");
      item.append("span").text(sector);
    });
  }

  /* ── Data Table ── */
  function buildTable(data) {
    /* Sort by sector then ticker for table display */
    const sorted = data.slice().sort(function (a, b) {
      const sd = d3.ascending(a.sector, b.sector);
      return sd !== 0 ? sd : d3.ascending(a.ticker, b.ticker);
    });

    const wrap  = d3.select("#table-wrap");
    const table = wrap.append("table");

    /* Header */
    const thead = table.append("thead").append("tr");
    ["Ticker Symbol", "Full Company Name", "Sector", "Market Cap"].forEach(function (h) {
      thead.append("th").text(h);
    });

    /* Body */
    const tbody = table.append("tbody");
    const rows = tbody.selectAll("tr")
      .data(sorted, function (d) { return d.ticker; })
      .join("tr")
      .attr("data-ticker", function (d) { return d.ticker; });

    rows.append("td").attr("class", "ticker-cell").text(function (d) { return d.ticker; });
    rows.append("td").text(function (d) { return d.name; });
    rows.append("td").attr("class", "sector-cell").each(function (d) {
      const color = SECTOR_COLORS[d.sector] || "#888";
      d3.select(this).append("span")
        .attr("class", "sector-badge")
        .style("background", color + "22")
        .style("color", color)
        .style("border", "1px solid " + color + "55")
        .text(d.sector);
    });
    rows.append("td").attr("class", "cap-cell")
      .text(function (d) { return formatMarketCap(d.marketCap); });

    /* Click on row → select */
    rows.on("click", function (event, d) {
      if (selectedTicker === d.ticker) {
        clearSelection();
      } else {
        selectTicker(d.ticker);
      }
    });

    window._tableRows = rows;
  }

  /* ── Selection helpers ── */
  function selectTicker(ticker) {
    selectedTicker = ticker;

    /* Bubble highlighting */
    if (window._bubbleNodes) {
      window._bubbleNodes.select("circle")
        .classed("selected", function (d) { return d.ticker === ticker; });
    }

    /* Row highlighting + scroll into view */
    if (window._tableRows) {
      window._tableRows.classed("selected", function (d) { return d.ticker === ticker; });
      const selectedRow = document.querySelector("tr[data-ticker='" + ticker + "']");
      if (selectedRow) {
        selectedRow.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }
    }
  }

  function clearSelection() {
    selectedTicker = null;
    if (window._bubbleNodes) {
      window._bubbleNodes.select("circle").classed("selected", false);
    }
    if (window._tableRows) {
      window._tableRows.classed("selected", false);
    }
  }

})();
